  const events = [];
  for await (const event of stream) events.push(event);
  return envelope("pi-provider-faux-stream", "provider", "@earendil-works/pi-ai", input, {
    events,
    finalMessage: await stream.result(),
    providerState: faux.state,
  }, {
    eventTypes: [
      "start", "thinking_start", "thinking_delta", "thinking_end", "text_start", "text_delta", "text_end",
      "toolcall_start", "toolcall_delta", "toolcall_end", "done",
