    log: await session.getLog(),
    leafId: await session.getLeafId(),
    openOperations: await session.findOpenOperations(input.lane),
  }, {
    logKinds: ["record", "entry", "record", "entry", "record", "entry", "record"],
    entryRoles: ["user", "assistant", "toolResult"],
  });
